/**
 * Code a pack runs on the server, apart from the app (Pack.server, API 2.1, #304): one bundled
 * ES module and the `wasm` modules it uses, called by name through `ctx.call(fn, input)`.
 *
 * Why apart: a Worker can't compile WebAssembly from bytes at run time, and a long synchronous
 * call can't be stopped from inside (`within` only stops waiting). So:
 * - Locally it runs in a worker thread of its own (one per pack), with no environment. A call
 *   that takes too long ends the thread; the next call starts a fresh one.
 * - Hosted it runs in a Worker of its own, generated by `src/packs/servers.ts` (the modules
 *   imported at build time), and is called over the service binding `SERVER_<ID>`. That Worker
 *   gets its own CPU limit and no bindings at all.
 *
 * Input and output are plain JSON, 4 MB at most each way. A call never throws: it answers
 * `{ ok: false, error }`.
 */
import type { Worker } from "node:worker_threads";
import type { Pack, PackCalled, PackServer } from "./types.ts";
import { fileWhy, isWasm, isWasmFile, sha16, shaOk } from "./wasm.ts";

/** JSON either way, at most (characters). */
export const SERVER_JSON_MAX = 4 * 1024 * 1024;
/** How long a call may take by default, and at most. */
export const SERVER_MS = 10_000;
export const SERVER_MS_MAX = 30_000;
/** The script: one bundled file. */
const SCRIPT_MAX = 8 * 1024 * 1024;

/** The service binding a pack's server is reached through, hosted: `SERVER_CODE_REVIEW`. */
export const serverBinding = (id: string) => `SERVER_${id.toUpperCase().replace(/-/g, "_")}`;
/** The entrypoint class the generated Worker exports. */
export const SERVER_ENTRYPOINT = "PackServer";
export const callNameOk = (fn: unknown): fn is string => typeof fn === "string" && /^[a-z][a-zA-Z0-9]{0,39}$/.test(fn);
/** How long this server's calls may take. */
export const serverMs = (s: PackServer) => Math.min(SERVER_MS_MAX, Math.max(100, Number.isFinite(s.ms) ? Number(s.ms) : SERVER_MS));

/** Why a pack's server can't run ("" when it can): its declaration, before anything is loaded. */
export function serverWhy(p: Pack): string {
  const s = p.server;
  if (!s) return "";
  if (!isWasmFile(s.script) || !shaOk(s.script.sha256)) return "its script needs a 16-digit hex sha256 and a load";
  if (!Array.isArray(s.calls) || !s.calls.length || !s.calls.every(callNameOk)) return "needs calls: camelCase names, at least one";
  for (const name of s.wasm ?? []) {
    const m = p.wasm?.[name];
    if (!m) return `uses wasm ${String(name).slice(0, 40)}, which the pack doesn't ship`;
  }
  return "";
}

/** The script's text, checked against its sha256. Throws why not. */
export async function serverScript(s: PackServer): Promise<string> {
  const b = await s.script.load();
  if (!(b instanceof Uint8Array)) throw new Error("its script isn't bytes");
  if (b.length > SCRIPT_MAX) throw new Error("its script is over 8 MB");
  const got = await sha16(b);
  if (got !== s.script.sha256) throw new Error(`its script has SHA-256 ${got}, not the ${s.script.sha256} it declares (rebuild the pack)`);
  return new TextDecoder().decode(b);
}

/** The modules it uses, as bytes, checked. Throws why not. */
export async function serverWasm(p: Pack): Promise<Record<string, Uint8Array>> {
  const out: Record<string, Uint8Array> = {};
  for (const name of p.server?.wasm ?? []) {
    const m = p.wasm![name]!;
    if (isWasmFile(m)) {
      const b = await m.load();
      const why = await fileWhy(b, m.sha256);
      if (why) throw new Error(`wasm ${name} ${why}`);
      out[name] = b;
    } else if (m instanceof Uint8Array && isWasm(m)) out[name] = m;
    else throw new Error(`wasm ${name} isn't WebAssembly`);
  }
  return out;
}

const short = (e: unknown) => String((e as Error)?.message ?? e).replace(/\s+/g, " ").slice(0, 300);

/** The input as JSON, or why it can't go. */
export function inputJson(fn: unknown, input: unknown, s: PackServer): { json: string } | { error: string } {
  if (!callNameOk(fn) || !s.calls.includes(fn)) return { error: `${String(fn).slice(0, 40)} isn't one of its calls` };
  let json: string | undefined;
  try {
    json = JSON.stringify(input ?? null);
  } catch (e) {
    return { error: `the input isn't JSON: ${short(e)}` };
  }
  if (json === undefined) return { error: "the input isn't JSON" };
  if (json.length > SERVER_JSON_MAX) return { error: "the input is over 4 MB" };
  return { json };
}

/** What came back, read. */
export function calledOf(json: unknown): PackCalled {
  if (typeof json !== "string") return { ok: false, error: "it answered something that isn't JSON" };
  if (json.length > SERVER_JSON_MAX) return { ok: false, error: "its answer is over 4 MB" };
  try {
    return { ok: true, value: JSON.parse(json) };
  } catch {
    return { ok: false, error: "it answered something that isn't JSON" };
  }
}

/** The worker thread's own code (CommonJS, evaluated): compiles the modules once, then answers calls in order. */
const BOOT = `
const { parentPort, workerData } = require("node:worker_threads");
const ready = (async () => {
  const wasm = {};
  for (const [n, b] of Object.entries(workerData.wasm)) wasm[n] = await WebAssembly.compile(b);
  const mod = await import(workerData.script);
  if (typeof mod.call !== "function") throw new Error("its script exports no call(fn, input, wasm)");
  return { mod, wasm };
})();
ready.catch(() => {});
parentPort.on("message", async ({ id, fn, input }) => {
  try {
    const { mod, wasm } = await ready;
    const value = await mod.call(fn, JSON.parse(input), wasm);
    parentPort.postMessage({ id, ok: true, json: JSON.stringify(value === undefined ? null : value) });
  } catch (e) {
    parentPort.postMessage({ id, ok: false, error: String((e && e.message) || e) });
  }
});
`;

export type ServerCall = (fn: unknown, input: unknown) => Promise<PackCalled>;

/**
 * Locally: the pack's server in a worker thread, started on the first call. Calls go one at a
 * time, so each one's time is its own. One over time ends the thread (and fails what waits behind it).
 */
export function localServer(p: Pack, log: (line: string) => void = () => {}): ServerCall & { stop(): Promise<void> } {
  const s = p.server!;
  const ms = serverMs(s);
  let loaded: Promise<{ script: string; wasm: Record<string, Uint8Array> }> | undefined;
  let thread: Worker | undefined;
  let next = 0;
  const waiting = new Map<number, (r: PackCalled) => void>();
  let queue: Promise<unknown> = Promise.resolve();

  const end = (why: string) => {
    const t = thread;
    thread = undefined;
    for (const [id, done] of waiting) {
      waiting.delete(id);
      done({ ok: false, error: why });
    }
    return t?.terminate().then(() => {}, () => {});
  };
  const start = async () => {
    loaded ??= (async () => ({ script: `data:text/javascript;base64,${Buffer.from(await serverScript(s)).toString("base64")}`, wasm: await serverWasm(p) }))();
    const { script, wasm } = await loaded;
    // No environment: what it needs comes in the input.
    // Imported here, not above: the hosted Worker bundles this file but never starts a thread.
    const { Worker } = await import("node:worker_threads");
    const t = new Worker(BOOT, { eval: true, workerData: { script, wasm }, env: {}, resourceLimits: { maxOldGenerationSizeMb: 512 } });
    t.unref();
    t.on("message", (m: { id: number; ok: boolean; json?: string; error?: string }) => {
      const done = waiting.get(m.id);
      if (!done) return;
      waiting.delete(m.id);
      done(m.ok ? calledOf(m.json) : { ok: false, error: short(m.error) });
    });
    t.on("error", (e) => {
      log(`server: ${short(e)}`);
      if (thread === t) void end(`its server stopped: ${short(e)}`);
    });
    t.on("exit", () => {
      if (thread === t) void end("its server stopped");
    });
    return t;
  };

  const one = async (fn: unknown, input: unknown): Promise<PackCalled> => {
    const asked = inputJson(fn, input, s);
    if ("error" in asked) return { ok: false, error: asked.error };
    try {
      thread ??= await start();
    } catch (e) {
      loaded = undefined;
      return { ok: false, error: `its server didn't start: ${short(e)}` };
    }
    const t = thread;
    const id = next++;
    return new Promise<PackCalled>((resolve) => {
      const timer = setTimeout(() => {
        log(`server: ${fn} took over ${ms} ms; stopped`);
        if (thread === t) void end(`${fn} took over ${ms / 1000} s; stopped`);
      }, ms);
      timer.unref?.();
      waiting.set(id, (r) => {
        clearTimeout(timer);
        resolve(r);
      });
      t.postMessage({ id, fn, input: asked.json });
    });
  };

  const call = ((fn: unknown, input: unknown) => {
    const r = queue.then(() => one(fn, input));
    queue = r.catch(() => {});
    return r;
  }) as ServerCall & { stop(): Promise<void> };
  call.stop = async () => {
    await end("its server stopped");
  };
  return call;
}

/** What the generated Worker's entrypoint offers over the binding. */
export type ServerBinding = { call(fn: string, input: string): Promise<string> };
const isBinding = (v: unknown): v is ServerBinding => !!v && typeof (v as ServerBinding).call === "function";

/** Hosted: the pack's server over its service binding. Waits its time plus a little for the Worker's own limit to answer first. */
export function boundServer(p: Pack, binding: unknown): ServerCall {
  const s = p.server!;
  const ms = serverMs(s) + 2000;
  const name = serverBinding(p.manifest.id);
  return async (fn, input) => {
    if (!isBinding(binding)) return { ok: false, error: `its server isn't bound here (${name}: run src/packs/servers.ts, deploy it, and add the service binding)` };
    const asked = inputJson(fn, input, s);
    if ("error" in asked) return { ok: false, error: asked.error };
    let timer: ReturnType<typeof setTimeout> | undefined;
    try {
      const json = await Promise.race([binding.call(fn as string, asked.json), new Promise<never>((_, no) => (timer = setTimeout(() => no(new Error(`${fn} took over ${ms / 1000} s`)), ms)))]);
      return calledOf(json);
    } catch (e) {
      return { ok: false, error: short(e) };
    } finally {
      clearTimeout(timer);
    }
  };
}
